contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: a target, value, data, predecessor, salt, and delay to test schedule behavior
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // Ensure this contract has the PROPOSER_ROLE by setting up via constructor steps done in C deployment
        // The fresh C instance is deployed by the harness; msg.sender for c calls will be this contract.

        // Read minDelay before attempting schedule
        uint256 minDelay = c.getMinDelay();

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Record timestamp before attempt
        uint256 tsBefore = c.getTimestamp(id);

        bool reverted;
        // attempt to schedule; schedule is non-view and must be a top-level call
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read timestamp after attempt
        uint256 tsAfter = c.getTimestamp(id);

        /* General rule:
           If delay < minDelay then schedule must revert (so reverted == true) and timestamp must remain unchanged (tsAfter == tsBefore).
           If delay >= minDelay then schedule must succeed (reverted == false) and operation becomes pending: tsAfter > 1 (i.e., > _DONE_TIMESTAMP) and tsAfter >= block.timestamp + minDelay (equivalently tsAfter >= block.timestamp + delay but we conservatively require > 1).
           We express the rule using only public getters and parameters.
        */
        if (delay < minDelay) {
            assert(reverted && tsAfter == tsBefore);
        } else {
            // When scheduling succeeds, reverted==false and timestamp becomes > 1
            assert(!reverted && tsAfter > 1);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: a target, value, data, predecessor, salt, and delay to test schedule behavior
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // Read minDelay before attempting schedule
        uint256 minDelay = c.getMinDelay();

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Record timestamp before attempt
        uint256 tsBefore = c.getTimestamp(id);

        // We will perform the schedule call as a top-level statement. Use low-level call to detect revert without try/catch.
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.schedule.selector, target, value, data, predecessor, salt, delay));

        // Read timestamp after attempt
        uint256 tsAfter = c.getTimestamp(id);

        // General rule as a single assert:
        // If delay < minDelay then the call must have reverted (ok == false) and timestamp unchanged;
        // If delay >= minDelay then the call must have succeeded (ok == true) and timestamp set to a pending value (> 1).
        assert( (delay < minDelay && !ok && tsAfter == tsBefore) || (delay >= minDelay && ok && tsAfter > 1) );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: target, value, data, predecessor, salt, delay
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // Compute id and read prior observable state
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        uint256 tsBefore = c.getTimestamp(id);
        uint256 minDelay = c.getMinDelay();

        // Attempt scheduling as a top-level call; capture revert with try/catch
        bool reverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 tsAfter = c.getTimestamp(id);

        // General rule:
        // If delay >= minDelay and the caller (this contract) has PROPOSER_ROLE then schedule must succeed and set timestamp > 1.
        // Otherwise the schedule call must revert and timestamp must remain unchanged.
        // We observe caller role by checking hasRole(PROPOSER_ROLE, address(this)).
        bytes32 PROPOSER = c.PROPOSER_ROLE();
        bool isProposer = c.hasRole(PROPOSER, address(this));

        assert(
            ((delay >= minDelay && isProposer) && !reverted && tsAfter > 1) ||
            (((delay < minDelay) || !isProposer) && reverted && tsAfter == tsBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters needed to form a single operation and a delay.
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // Precondition: require that this test contract already has the PROPOSER_ROLE so scheduling should be permitted.
        bytes32 PROPOSER = c.PROPOSER_ROLE();
        require(c.hasRole(PROPOSER, address(this)), "precondition: test contract must have PROPOSER_ROLE");

        // Also require delay >= minDelay to focus the property on the successful scheduling case.
        uint256 minDelay = c.getMinDelay();
        require(delay >= minDelay, "precondition: delay must be >= minDelay");

        // Compute the id and snapshot timestamp before.
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        uint256 tsBefore = c.getTimestamp(id);

        // Make the state-changing call as a top-level statement and catch revert.
        bool reverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read timestamp after.
        uint256 tsAfter = c.getTimestamp(id);

        // Assert the general rule: because caller has PROPOSER_ROLE and delay >= minDelay,
        // schedule must not revert and must set the operation timestamp to a value > 1.
        assert(reverted == false && tsAfter > 1 && tsAfter != tsBefore);
    }

    receive() external payable {}
}

