contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // ensure this contract has proposer role: the constructor of C gave TIMELock admin to deployer and the contract itself,
        // but we cannot assume proposers. Instead, try scheduling and record whether it reverted.

        // read min delay before attempt
        uint256 minDelay = c.getMinDelay();

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // try schedule and capture revert
        bool reverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // after the attempt, observe timestamp and isOperation
        uint256 ts = c.getTimestamp(id);
        bool isOp = c.isOperation(id);

        // General rule:
        // - If delay < minDelay then schedule must revert (reverted==true) and operation must not be scheduled (isOp==false and ts==0).
        // - If delay >= minDelay then schedule must not revert (reverted==false) and operation must be scheduled: isOp==true and ts >= block.timestamp (timestamp set to block.timestamp+delay),
        //   and ts != 0.
        // We express this as a single assert combining both cases.

        assert(
            (delay < minDelay && reverted && !isOp && ts == 0) ||
            (delay >= minDelay && !reverted && isOp && ts != 0 && ts >= block.timestamp)
        );
    }

    receive() external payable {}
}
